//! CameraPreview widget — self-drawn simulated camera viewfinder preview.
//!
//! This is a simulated preview component: it never opens or reads from a real
//! camera device. It draws a stylized viewfinder (resolution label, camera id,
//! zoom/mirror indicators, crosshair, control overlay) and manages a local
//! active state. There is no video feed behind the widget; all visuals are
//! generated by the widget itself.

use crate::core::{Color, HorizontalAlignment, Point, Rect};
use crate::event::{Event, EventHandler};
use crate::impl_widget_property_hooks;
use crate::property_names_of;
use crate::render::RenderContext;
use crate::signal::{GenericSignal, Signal1};
use crate::widget::capability::coercion::expect_bool;
use crate::widget::capability::properties_trait::{base_property_get, base_property_set};
use crate::widget::capability::types::{CapabilityAccessError, CapabilityValue};
use crate::widget::capability::WidgetProperties;
use crate::widget::metrics::role_font;
use crate::widget::{BaseWidget, Draw, Widget, WidgetKind};

/// The inactive viewfinder's fill.
///
/// The off-state viewport is the placeholder for a video surface, so it is a near-black that
/// does not follow the appearance — that is the `video-surface` exemption's subject. It is a
/// named constant because the "Camera Off" label is chrome drawn on it and must stay legible
/// against it, so both must read the same value.
const EMPTY_VIEWFINDER: Color = Color::rgba(50, 50, 60, 255);

/// The active viewfinder's fill, used when neither the style nor the theme names one.
///
/// A camera feed is judged against a neutral dark ground in every camera application, so the
/// stage keeps this cave-dark default rather than following the appearance. What *does* follow is
/// the ink drawn on it: the overlay labels are derived from whatever stage is painted, so a host
/// that sets a light stage through the style still gets legible annotation. It is a named
/// constant for the same reason as [`EMPTY_VIEWFINDER`] — the stage and its fallback must be one
/// value, not two that can drift.
const ACTIVE_VIEWFINDER: Color = Color::rgba(30, 30, 40, 255);

/// A decoded camera frame supplied by the host.
///
/// The data is tightly packed RGBA, row-major, with no padding between rows. The widget never
/// captures or decodes anything itself; it paints what the host hands it.
#[derive(Debug, Clone)]
pub struct CameraFrame {
    /// Frame width in pixels.
    pub width: u32,
    /// Frame height in pixels.
    pub height: u32,
    /// RGBA bytes, `width * height * 4` long.
    pub data: Vec<u8>,
}

/// Camera preview widget — draws a simulated camera viewfinder area with controls.
///
/// Renders a self-drawn camera viewfinder and optional control overlay buttons.
/// Zoom, mirror/flip and preview start/stop only change local widget state and
/// redrawing; no real camera device is opened and no frames are captured.
pub struct CameraPreview {
    base: BaseWidget,
    /// Whether the camera preview is currently active.
    is_active: bool,
    /// Camera resolution as (width, height).
    resolution: (u32, u32),
    /// Camera device identifier.
    camera_id: u32,
    /// Whether the preview is mirrored (horizontally flipped).
    mirror_mode: bool,
    /// Whether control buttons are shown overlaid on the preview.
    show_controls: bool,
    /// Current zoom level (1.0 = normal).
    zoom_level: f32,
    /// The most recent frame supplied by the host, if any.
    frame: Option<CameraFrame>,
    /// Emitted when the host reports a capture failure.
    pub error_occurred: Signal1<String>,
    /// Emitted when the host reports that camera permission was denied.
    pub permission_denied: GenericSignal,
}

impl CameraPreview {
    /// Creates a new CameraPreview widget with the given geometry.
    pub fn new(geometry: Rect) -> Self {
        Self {
            base: BaseWidget::new(WidgetKind::CameraPreview, geometry, "CameraPreview"),
            is_active: false,
            resolution: (640, 480),
            camera_id: 0,
            mirror_mode: false,
            show_controls: true,
            zoom_level: 1.0,
            frame: None,
            error_occurred: Signal1::new(),
            permission_denied: GenericSignal::new(),
        }
    }

    /// Starts the simulated camera preview.
    ///
    /// Only flips the local active flag and requests a redraw. No camera device
    /// is opened and no frames are captured; the "preview" shown is drawn by
    /// this widget itself.
    pub fn start_preview(&mut self) {
        self.is_active = true;
        self.base.request_redraw();
    }

    /// Stops the simulated camera preview (local state and redraw only).
    pub fn stop_preview(&mut self) {
        self.is_active = false;
        self.base.request_redraw();
    }

    /// Returns whether the camera preview is active.
    pub fn is_active(&self) -> bool {
        self.is_active
    }

    /// Toggles the simulated preview on/off (local state only).
    pub fn toggle_preview(&mut self) {
        if self.is_active {
            self.stop_preview();
        } else {
            self.start_preview();
        }
    }

    /// Sets the camera device identifier shown in the preview overlay.
    ///
    /// Display-only: no device with this id is opened or streamed from.
    pub fn set_camera_id(&mut self, id: u32) {
        if self.camera_id == id {
            return;
        }
        self.camera_id = id;
        // `draw` labels the preview with the device it shows, so the caption goes stale without
        // this.
        self.base.request_redraw();
    }

    /// Returns the current camera device ID.
    pub fn camera_id(&self) -> u32 {
        self.camera_id
    }

    /// Sets the resolution label used by the simulated preview.
    ///
    /// Used for the on-screen "WxH" text; no capture pipeline exists.
    pub fn set_resolution(&mut self, w: u32, h: u32) {
        let resolution = (w.max(1), h.max(1));
        if self.resolution == resolution {
            return;
        }
        self.resolution = resolution;
        self.base.request_redraw();
    }

    /// Returns the current camera resolution.
    pub fn resolution(&self) -> (u32, u32) {
        self.resolution
    }

    /// Enables or disables mirror mode (horizontal flip).
    pub fn set_mirror_mode(&mut self, mirrored: bool) {
        if self.mirror_mode == mirrored {
            return;
        }
        self.mirror_mode = mirrored;
        self.base.request_redraw();
    }

    /// Returns whether mirror mode is enabled.
    pub fn is_mirror_mode(&self) -> bool {
        self.mirror_mode
    }

    /// Sets the zoom level (1.0 = normal, 2.0 = 2x, etc.).
    pub fn set_zoom(&mut self, level: f32) {
        let level = level.clamp(1.0, 10.0);
        if self.zoom_level == level {
            return;
        }
        self.zoom_level = level;
        self.base.request_redraw();
    }

    /// Supplies a decoded RGBA frame for the viewfinder.
    ///
    /// The frame's own dimensions become the preview's resolution, which is what makes
    /// [`Self::set_resolution`] a *format negotiation* rather than a label: the picture and the
    /// readout name the same size because both come from the frame that is on screen. Returns
    /// `Err` when the dimensions are empty or the byte count is not `width * height * 4`.
    pub fn set_frame(&mut self, width: u32, height: u32, data: &[u8]) -> Result<(), String> {
        if width == 0 || height == 0 {
            return Err("a camera frame needs non-zero dimensions".to_string());
        }
        let expected = (width as usize) * (height as usize) * 4;
        if data.len() != expected {
            return Err(format!(
                "a {width}x{height} RGBA frame needs {expected} bytes, got {}",
                data.len()
            ));
        }
        self.frame = Some(CameraFrame { width, height, data: data.to_vec() });
        self.resolution = (width, height);
        self.base.request_redraw();
        Ok(())
    }

    /// Removes the host frame, returning the viewfinder to its simulated drawing.
    pub fn clear_frame(&mut self) {
        if self.frame.take().is_some() {
            self.base.request_redraw();
        }
    }

    /// Returns the most recent host frame, if any.
    pub fn frame(&self) -> Option<&CameraFrame> {
        self.frame.as_ref()
    }

    /// Reports a capture failure to the host's listeners.
    pub fn report_error(&mut self, message: impl Into<String>) {
        self.error_occurred.emit(message.into());
    }

    /// Reports that camera permission was denied, which is its own state rather than a
    /// generic error: a host normally shows different remediation for the two.
    pub fn report_permission_denied(&mut self) {
        self.permission_denied.emit();
    }

    /// Returns the current zoom level.
    pub fn zoom_level(&self) -> f32 {
        self.zoom_level
    }

    /// Zooms in by one step.
    pub fn zoom_in(&mut self) {
        self.set_zoom(self.zoom_level + 0.5);
    }

    /// Zooms out by one step.
    pub fn zoom_out(&mut self) {
        self.set_zoom(self.zoom_level - 0.5);
    }

    /// Makes the control overlay visible.
    pub fn show_controls(&mut self) {
        self.show_controls = true;
        self.base.request_redraw();
    }

    /// Hides the control overlay.
    pub fn hide_controls(&mut self) {
        self.show_controls = false;
        self.base.request_redraw();
    }

    /// Returns whether controls are currently visible.
    pub fn controls_visible(&self) -> bool {
        self.show_controls
    }
}

impl Widget for CameraPreview {
    fn base(&self) -> &BaseWidget {
        &self.base
    }
    fn set_state_theme_hook(&mut self) {
        crate::style::reapply_active_theme_state(self);
    }
    fn base_mut(&mut self) -> &mut BaseWidget {
        &mut self.base
    }

    fn size_hint(&self) -> crate::core::Size {
        crate::core::Size::new(320, 240)
    }

    /// Reports this widget as the object that paints it.
    ///
    /// `CameraPreview` implements `Draw`, so `Some(self)` is total and cannot be
    /// wrong.
    fn as_draw_mut(&mut self) -> Option<&mut dyn crate::widget::Draw> {
        Some(self)
    }

    impl_widget_property_hooks!();
}

/// `CameraPreview`'s property contract.
///
/// Read/write semantics are carried over unchanged from the centralised
/// `access_read_media.in.rs` / `access_write_media.in.rs` dispatch: `is_active`
/// maps onto `start_preview` / `stop_preview`.
impl WidgetProperties for CameraPreview {
    fn get(&self, name: &str) -> Result<CapabilityValue, CapabilityAccessError> {
        match name {
            "is_active" => Ok(CapabilityValue::Bool(self.is_active())),
            _ => base_property_get(self, name),
        }
    }

    fn set(&mut self, name: &str, value: CapabilityValue) -> Result<(), CapabilityAccessError> {
        match name {
            "is_active" => {
                if expect_bool(value)? {
                    self.start_preview();
                } else {
                    self.stop_preview();
                }
                Ok(())
            }
            _ => base_property_set(self, name, value),
        }
    }

    fn property_names(&self) -> &'static [&'static str] {
        property_names_of!["is_active", BASE_PROPERTY_NAMES]
    }
}

impl Draw for CameraPreview {
    fn draw(&mut self, context: &mut RenderContext) {
        let rect = self.geometry();
        let w = rect.width as i32;
        let h = rect.height as i32;

        if w <= 0 || h <= 0 {
            return;
        }

        // ── Viewfinder chrome ────────────────────────────────────────────
        //
        // The overlay ink and the viewfinder fill are **chrome**: a resolution readout, a camera
        // id, a zoom label and a crosshair are annotations *about* the picture, not the picture.
        // They were eight hardcoded `rgba(2xx,2xx,2xx)` values, so a light appearance produced
        // white-on-near-white labels — measured at **1.15:1**, i.e. invisible — with nothing
        // reported, and a theme switch moved nothing but the page behind them. This is the same
        // defect shape `image_gallery`'s stage overlay had.
        //
        // The active viewfinder stays dark on purpose: a camera feed is judged against a neutral
        // dark ground, and every camera app does this. So the *stage* keeps its dark default,
        // while the ink on it is derived from that stage — which is what keeps the escape hatch
        // the old literals were reaching for (a light stage still gets legible ink) without the
        // theme being unable to move anything.
        let style = self.base.style();
        // The overlay text uses the control's **role fonts**, so the theme face and the user's
        // text scale reach it. They were `Font::new("sans-serif", …)` built before the style
        // was even read.
        let small_font = role_font(style, 11.0);
        let normal_font = role_font(style, 13.0);
        let theme = crate::style::resolved_theme_style_shared("camera_preview");
        // A host that gave the control an explicit colour wins; otherwise the dark stage default.
        let viewfinder = style
            .background_color
            .or_else(|| theme.as_ref().and_then(|t| t.background_color))
            .unwrap_or(ACTIVE_VIEWFINDER);
        // One step from the stage toward its own contrast colour, so the overlay is legible on
        // whatever stage is painted. On the default stage this is the old near-white.
        let stage_ink = viewfinder.contrast_color();
        let label_ink = viewfinder.blend(&stage_ink, 0.78);
        let strong_ink = viewfinder.blend(&stage_ink, 0.86);
        let crosshair_ink = viewfinder.blend(&stage_ink, 0.55);

        if self.is_active {
            // Draw active camera view — dark viewfinder area
            context.fill_rect(rect, viewfinder);

            // The host's frame is painted at its own pixel size, centred and clipped to the
            // preview. Content, not chrome: it is the caller's picture and is never recoloured.
            if let Some(frame) = self.frame.as_ref() {
                let dx = rect.x + (w - frame.width as i32) / 2;
                let dy = rect.y + (h - frame.height as i32) / 2;
                context.push_clip(rect.x, rect.y, rect.width, rect.height);
                context.draw_image(dx.max(0), dy.max(0), frame.width, frame.height, &frame.data);
                context.pop_clip();
            }

            // Draw resolution info text
            let res_text = format!("{}x{}", self.resolution.0, self.resolution.1);
            context.draw_text(
                Point::new(rect.x + 6, rect.y + 14),
                &res_text,
                &small_font,
                label_ink,
                HorizontalAlignment::Left,
            );

            // Draw camera ID
            let id_text = format!("Camera #{}", self.camera_id);
            context.draw_text(
                Point::new(rect.x + 6, rect.y + h - 10),
                &id_text,
                &small_font,
                label_ink,
                HorizontalAlignment::Left,
            );

            // Draw zoom level indicator
            let zoom_text = format!("{:.1}x", self.zoom_level);
            context.draw_text(
                Point::new(rect.x + w - 40, rect.y + 14),
                &zoom_text,
                &normal_font,
                strong_ink,
                HorizontalAlignment::Left,
            );

            // Draw mirror indicator
            if self.mirror_mode {
                context.draw_text(
                    Point::new(rect.x + w / 2 - 20, rect.y + h - 10),
                    "MIRROR",
                    &small_font,
                    viewfinder.blend(&stage_ink, 0.68),
                    HorizontalAlignment::Left,
                );
            }

            // Draw a subtle crosshair
            let cx = rect.x + w / 2;
            let cy = rect.y + h / 2;
            let crosshair_color = crosshair_ink;
            context.draw_line(Point::new(cx, cy - 15), Point::new(cx, cy + 15), crosshair_color);
            context.draw_line(Point::new(cx - 15, cy), Point::new(cx + 15, cy), crosshair_color);

            // Draw border indicating active preview
            let border_color = Color::rgba(0, 200, 50, 200);
            context.draw_rect_stroke(rect, border_color, 2);

            // Draw control overlay if visible
            if self.show_controls {
                // Top-right corner controls background
                let control_bg = Rect::new(rect.x + w - 44, rect.y + 4, 40, 80);
                context.fill_rect(control_bg, Color::rgba(0, 0, 0, 120));

                // Draw zoom +/- buttons as simple colored rects
                let zoom_in_btn = Rect::new(rect.x + w - 42, rect.y + 6, 36, 36);
                context.fill_rect(zoom_in_btn, Color::rgba(255, 255, 255, 80));

                let zoom_out_btn = Rect::new(rect.x + w - 42, rect.y + 46, 36, 36);
                context.fill_rect(zoom_out_btn, Color::rgba(255, 255, 255, 80));
            }

            // Draw a green "recording" dot indicator
            let dot_size = 8;
            let dot_rect = Rect::new(rect.x + 6, rect.y + 6, dot_size, dot_size);
            context.fill_rect(dot_rect, Color::rgba(0, 255, 0, 255));
        } else {
            // Draw inactive camera view — dark gray with camera icon placeholder. The colour is
            // named because the label over it is derived from it, so the two cannot drift.
            context.fill_rect(rect, EMPTY_VIEWFINDER);

            // Draw a simple camera icon placeholder (rounded rectangle shape)
            let icon_w = 48u32;
            let icon_h = 36u32;
            let icon_x = rect.x + (w - icon_w as i32) / 2;
            let icon_y = rect.y + (h - icon_h as i32) / 2 - 10;
            let icon_rect = Rect::new(icon_x, icon_y, icon_w, icon_h);
            context.fill_rounded_rect(icon_rect, 6, Color::rgba(100, 100, 120, 200));

            // Lens circle
            let lens_center_x = icon_x + icon_w as i32 / 2;
            let lens_center_y = icon_y + icon_h as i32 / 2;
            let lens_rect = Rect::new(lens_center_x - 8, lens_center_y - 8, 16, 16);
            context.fill_rounded_rect(lens_rect, 8, Color::rgba(70, 70, 90, 255));

            // Flash dot
            let flash_rect = Rect::new(icon_x + icon_w as i32 - 10, icon_y + 4, 6, 6);
            context.fill_rounded_rect(flash_rect, 3, Color::rgba(200, 200, 200, 150));

            // "Camera Off" label. The viewport's near-black is the *content* placeholder — that
            // is what the `video-surface` exemption covers — but this label is chrome: it states
            // the state rather than being the frame, so it is held legible against the surface it
            // is painted on. The literal `rgba(150,150,160,200)` composited to `128,128,138` on
            // that `50,50,60` and measured 3.24:1, under the 4.5:1 body-text floor.
            let empty_surface = EMPTY_VIEWFINDER;
            context.draw_text(
                Point::new(rect.x + w / 2 - 30, rect.y + h / 2 + 20),
                "Camera Off",
                &normal_font,
                empty_surface.contrast_color().with_alpha(200),
                HorizontalAlignment::Left,
            );

            // Border
            context.draw_rect_stroke(rect, Color::rgba(100, 100, 110, 200), 1);
        }
    }
}

impl EventHandler for CameraPreview {
    fn handle_event(&mut self, event: &Event) {
        if !self.base.is_enabled() {
            return;
        }
        match event {
            Event::MousePress { pos, button, .. } => {
                // The press must land on the preview. Discarding the position meant a
                // click anywhere in the window started or stopped the camera — a
                // side-effecting device action taken on an unrelated click.
                if *button == 1 && self.geometry().contains_point(*pos) {
                    self.toggle_preview();
                }
            }
            _ => {
                self.base.handle_event(event);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn camera_preview_default_state() {
        let cp = CameraPreview::new(Rect::new(0, 0, 320, 240));
        assert!(!cp.is_active());
        assert_eq!(cp.camera_id(), 0);
        assert_eq!(cp.resolution(), (640, 480));
        assert!(!cp.is_mirror_mode());
        assert!(cp.controls_visible());
        assert!((cp.zoom_level() - 1.0).abs() < f32::EPSILON);
        assert_eq!(cp.kind(), WidgetKind::CameraPreview);
    }

    #[test]
    fn camera_preview_toggle() {
        let mut cp = CameraPreview::new(Rect::new(0, 0, 320, 240));
        assert!(!cp.is_active());
        cp.start_preview();
        assert!(cp.is_active());
        cp.stop_preview();
        assert!(!cp.is_active());
        cp.toggle_preview();
        assert!(cp.is_active());
        cp.toggle_preview();
        assert!(!cp.is_active());
    }

    #[test]
    fn camera_preview_zoom() {
        let mut cp = CameraPreview::new(Rect::new(0, 0, 320, 240));
        assert!((cp.zoom_level() - 1.0).abs() < f32::EPSILON);
        cp.zoom_in();
        assert!((cp.zoom_level() - 1.5).abs() < f32::EPSILON);
        cp.zoom_in();
        assert!((cp.zoom_level() - 2.0).abs() < f32::EPSILON);
        cp.zoom_out();
        assert!((cp.zoom_level() - 1.5).abs() < f32::EPSILON);
        cp.set_zoom(5.0);
        assert!((cp.zoom_level() - 5.0).abs() < f32::EPSILON);
    }

    #[test]
    fn camera_preview_camera_id_and_resolution() {
        let mut cp = CameraPreview::new(Rect::new(0, 0, 320, 240));
        cp.set_camera_id(2);
        assert_eq!(cp.camera_id(), 2);
        cp.set_resolution(1920, 1080);
        assert_eq!(cp.resolution(), (1920, 1080));
    }

    #[test]
    fn camera_preview_mirror_and_controls() {
        let mut cp = CameraPreview::new(Rect::new(0, 0, 320, 240));
        assert!(!cp.is_mirror_mode());
        cp.set_mirror_mode(true);
        assert!(cp.is_mirror_mode());
        assert!(cp.controls_visible());
        cp.hide_controls();
        assert!(!cp.controls_visible());
        cp.show_controls();
        assert!(cp.controls_visible());
    }

    #[test]
    fn camera_preview_click_toggles() {
        let mut cp = CameraPreview::new(Rect::new(0, 0, 320, 240));
        assert!(!cp.is_active());
        cp.handle_event(&Event::MousePress { pos: Point::new(10, 10), button: 1, modifiers: 0 });
        assert!(cp.is_active());
        cp.handle_event(&Event::MousePress { pos: Point::new(10, 10), button: 1, modifiers: 0 });
        assert!(!cp.is_active());
    }

    #[test]
    fn setting_the_camera_id_repaints() {
        let mut preview = CameraPreview::new(Rect::new(0, 0, 200, 200));
        let seen = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        preview.base.redraw_requested.connect({
            let seen = std::sync::Arc::clone(&seen);
            move || {
                seen.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            }
        });

        preview.set_camera_id(4);
        assert_eq!(
            seen.load(std::sync::atomic::Ordering::SeqCst),
            1,
            "the caption names the device, so it is painted"
        );
        preview.set_camera_id(4);
        assert_eq!(
            seen.load(std::sync::atomic::Ordering::SeqCst),
            1,
            "the same id is not a change"
        );
    }

    #[test]
    fn a_host_frame_negotiates_the_resolution_and_paints() {
        let mut preview = CameraPreview::new(Rect::new(0, 0, 320, 240));
        preview.start_preview();
        let data = vec![200u8; 4 * 4 * 4];
        preview.set_frame(4, 4, &data).expect("a matching byte count is accepted");
        assert_eq!(preview.resolution(), (4, 4));
        assert_eq!(preview.frame().map(|frame| frame.width), Some(4));
        let svg = crate::widget::svg::render_to_svg(&mut preview);
        assert!(svg.starts_with("<svg"));
    }

    #[test]
    fn a_malformed_frame_is_refused_rather_than_painted() {
        let mut preview = CameraPreview::new(Rect::new(0, 0, 320, 240));
        assert!(preview.set_frame(2, 2, &[0u8; 8]).is_err());
        assert!(preview.frame().is_none());
    }

    #[test]
    fn permission_is_reported_as_its_own_state() {
        let mut preview = CameraPreview::new(Rect::new(0, 0, 320, 240));
        let denied = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let d = denied.clone();
        preview.permission_denied.connect(move || {
            d.store(true, std::sync::atomic::Ordering::SeqCst);
        });
        preview.report_permission_denied();
        assert!(denied.load(std::sync::atomic::Ordering::SeqCst));
    }
}
